"""Coarse token classes: a small, readable guess at the component's typical value.

The component's activation is MLP hidden unit 2499 of layer 15 (scaled by about 0.67). Its
value is dense and depends on context that no token list captures; the means below are
the average activation of each coarse token class on training rows, the only signal
found that is simple enough to write down.
"""

READS = ()

PUNCTUATION = {",", ".", ":", ";"}
CONNECTIVES = {"in", "with", "by", "at", "as", "of", "for", "which", "and", "to", "on",
               "from", "that", "but", "while", "where", "when"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    if word == "(":
        value = 0.11
    elif word in PUNCTUATION:
        value = 0.05
    elif word.isdigit():
        value = 0.04
    elif word.lower() in CONNECTIVES:
        value = 0.0
    else:
        value = 0.015
    return carry, value

"""Layer 15 MLP hidden unit 2503 (this component reads almost only that unit).

Plain-terms summary: the component goes negative on words that head a noun phrase
about people or things, where a qualifier is likely to follow: bare plural nouns
("for patients", "in cells", "products that ..."), "those", "ones", "even", "anyone".
It is most negative for plural nouns that end a prepositional phrase ("for people",
"from students"). Most other tokens sit near zero; singular and mass nouns stay near
zero. These word rules explain only a few percent of its variance: the activation is
diffuse and depends on context the rules do not see.
"""

from functools import lru_cache

from wordnet import parts_of_speech

READS = ()

PREPOSITIONS = {"for", "from", "in", "to", "by", "of", "on", "with", "as", "at", "among",
                "about", "than", "like", "without", "across", "under", "during", "after",
                "before", "into", "between"}
GROUP_NOUNS = {"people", "patients", "participants", "individuals", "adults", "women",
               "men", "students", "children", "users", "players", "workers", "persons",
               "animals", "cells", "genes", "samples", "person"}
QUANTIFIER_HEADS = {"those", "ones", "even", "anyone", "anything", "someone", "something",
                    "everyone", "especially", "particularly"}
COMPARATIVE_WORDS = {"in", "for", "than", "among"}


@lru_cache(maxsize=None)
def is_plural_noun(word):
    return len(word) > 3 and word.endswith("s") and "noun" in parts_of_speech(word)


def step(carry, prefix, upstream):
    if prefix.position == 0 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, 0.0
    word = prefix.token_strings[-1].strip().lower()
    before = prefix.token_strings[-2].strip().lower()
    if word in GROUP_NOUNS:
        value = -1.3
    elif word in QUANTIFIER_HEADS:
        value = -1.3
    elif is_plural_noun(word) and before in PREPOSITIONS:
        value = -0.8
    elif is_plural_noun(word):
        value = -0.25
    elif word in COMPARATIVE_WORDS:
        value = -0.3
    else:
        value = 0.0
    return carry, value

"""Exemplification-introducer detector for the L15 MLP down_proj component 2508.

What it does: this component writes along a direction that, when its activation is
negative, pushes the next-token prediction toward example words (" example",
" instance", "为例", "例如", ...). So it is strongly negative on the words that set up
or complete a stock phrase that introduces an example, and near zero elsewhere:

  "for [example]", "for [instance]", "an [example]"      -> strongly negative
  "In [particular]"                                     -> negative
  "One [of]", "Examples [of]", "example [of]"           -> negative
  "..., [among] ..."  and Chinese 例如 / 比如 / 为例      -> mildly negative
  "..., [for]" (the "for" that often leads into an example) -> mildly negative
  any other "example"/"instance"                        -> slightly negative

The program is a small rule over the current token and the token before it. The
values were fitted by least squares on training rows, then rounded.
"""

READS = ()

EXAMPLE_WORDS = {
    "example", "examples", "instance", "instances", "Example", "Examples",
    "exemplo", "exemple", "ejemplo", "Beispiel", "пример", "имер",
}
INTRODUCERS = {"for", "For", "an", "An", "as", "As", "such", "e.g", "e.g."}
OF_HEADS = {"One", "Examples", "example", "Example", "examples", "Two", "First"}
ZH_EXAMPLE_WORDS = {"例", "例如", "比如", "举例", "为例"}


def value_of(cur, prev):
    """Predicted activation for token `cur`, given the token before it, `prev`."""
    cur, prev = cur.strip(), prev.strip()
    if cur in EXAMPLE_WORDS:
        return -5.5 if prev in INTRODUCERS else -0.7
    if cur == "particular" and prev in {"In", "in"}:
        return -3.8
    if cur == "of" and prev in OF_HEADS:
        return -3.2
    if cur in {"among", "Among"}:
        return -1.3
    if cur in ZH_EXAMPLE_WORDS:
        return -1.4
    if cur == "for" and prev == ",":
        return -1.0
    return 0.0


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2] if same_doc else ""
    return carry, float(value_of(cur, prev))

"""Lexical proxy for MLP hidden unit 2523 of layer 15 (the down_proj component 2523).

This unit is diffuse: no word list explains most of its variance. What it does respond to,
on training text, is a few word classes, so this program predicts those levels and 0 elsewhere:
  * words for taking part in a team, event or role ("team", "played", "competed",
    "appeared", "served", "member", ...): high;
  * "was" straight after a subject pronoun ("he was", "it was"): moderately high;
  * the articles and "one"/"first" in phrases like "one of the first": a little positive;
  * programming error words ("err", "async", "await", "failed", ...): negative.
"""
from collections.abc import Mapping

READS: tuple[str, ...] = ()

PARTICIPATION = {
    "team", "squad", "played", "competed", "participated", "participant",
    "appeared", "served", "scored", "appointed", "featured", "joined",
    "contributed", "member", "worked", "attended", "champion", "substitute",
}
PRONOUNS = {"he", "she", "it", "i", "they", "we"}
ARTICLES = {"the", "a", "an"}
ERRORS = {"err", "error", "async", "await", "failed", "fail", "isinstance", "bool", ".git"}


def step(carry, prefix, upstream: Mapping):
    word = prefix.token_strings[-1].strip().lower()
    before = prefix.token_strings[-2].strip().lower() if len(prefix.token_ids) > 1 else ""
    if word in PARTICIPATION:
        return carry, 0.8
    if word == "was":
        return carry, 0.6 if before in PRONOUNS else 0.1
    if word in ARTICLES:
        return carry, 0.1
    if word in {"one", "first"}:
        return carry, 0.2
    if word in ERRORS:
        return carry, -0.4
    return carry, 0.0

"""Arithmetic-operation slot detector, for layer 15's MLP down_proj component 2528.

This component's activation is mostly the MLP hidden unit 2528 of layer 15. It is small
and noisy almost everywhere, and it is large in one kind of place: where arithmetic is
being written out. Its biggest values come on the connecting word right after an operation
is named ("multiply [by]", "divide [by]", "multiplied [by]", "[then]"), and it is moderately
positive on multiplicative symbols (*, /, ×) inside math text. Elsewhere it sits slightly
below zero. This program predicts those group means and nothing finer.
"""

import re
from collections.abc import Mapping

READS: tuple[str, ...] = ()

OPERATION_NAMED = re.compile(r"multipl|divid|times|subtract|\badd|product|quotient")
MATH_TOKEN = re.compile(
    r"\d+|[+\-*/×÷=^()\[\]{}\\·]+|[a-z]|\\[a-z]+|\$+|by|times|then|divided|multipl\w*|add\w*"
    r"|subtract\w*|plus|minus|equals?|so|therefore"
)
CONNECTIVES = {"by", "then", "using", "with", "times"}
MULTIPLICATIVE = {"*", "/", "×", "·", "÷", "cdot", ")*", "*(", ")/", "×(", ")×"}
ADDITIVE = {"+", "-", "=", "−"}
FUNCTION_WORDS = {"is", "as", "or", "are", "be", "that", "of", "the", "for", "to", "a", "an",
                  "in", "with", "on", "by", "from", "and"}
PUNCTUATION = {".", ",", "\n", "\n\n", ")", "("}


def step(carry, prefix, upstream: Mapping):
    token = prefix.token_strings[-1].strip()
    doc = prefix.document_ids[-1]
    # the up to 16 tokens before this one, in the same document, newest first
    before = []
    for i in range(len(prefix.token_ids) - 2, max(-1, len(prefix.token_ids) - 18), -1):
        if prefix.document_ids[i] != doc:
            break
        before.append(prefix.token_strings[i].strip().lower())
    math_density = sum(bool(MATH_TOKEN.fullmatch(s)) for s in before) / max(1, len(before))
    operation_named = any(OPERATION_NAMED.search(s) for s in before[:3])

    if token in CONNECTIVES:
        if operation_named:
            return carry, 1.4
        if math_density > 0.4:
            return carry, 0.3
    if token in MULTIPLICATIVE:
        return carry, 0.35 if math_density > 0.3 else 0.06
    if token in ADDITIVE:
        return carry, -0.07
    if token in FUNCTION_WORDS:
        return carry, -0.04
    if token in PUNCTUATION:
        return carry, -0.05
    return carry, -0.02

"""Layer 15, MLP hidden unit 2530, read as a rough causal rule. The component reads that
unit almost alone (its input direction is about 0.84 on it), so its activation is that
unit's value times the norm of its output column. The activation has std about 0.7, with
rare spikes of 10-20 in both signs, and it is not set by the current token's identity alone.

The rule uses only the prefix, and resets at each document start:
  * the kind of the current token: number, whitespace, punctuation, or word;
  * whether the current bigram (previous token, current token) already appeared in this
    document;
  * whether the token that followed the previous occurrence of the current token (the
    copy guess) is a single digit.
Predicted value = a small offset per kind, plus a bump for a repeated bigram and for a
copied digit. Weights are a least-squares fit on training rows. It explains under 1% of
the variance, so it is a weak description, not a full explanation.
"""

import re

READS = ()

KIND_VALUE = {"num": -0.10, "space": 0.14, "punct": 0.05, "word": -0.03}
BIGRAM_BUMP = 0.008
COPIED_DIGIT_BUMP = 0.087


def kind_of(text):
    s = text.strip()
    if re.fullmatch(r"\d+", s):
        return "num"
    if s == "":
        return "space"
    if re.fullmatch(r"[\W_]+", s):
        return "punct"
    return "word"


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry["doc"] != doc:
        carry = {"doc": doc, "last": {}, "bigrams": set(), "prev": None}
    cur = prefix.token_ids[-1]
    t = prefix.position
    value = KIND_VALUE[kind_of(prefix.token_strings[-1])]
    bigram = (carry["prev"], cur)
    if bigram in carry["bigrams"]:
        value += BIGRAM_BUMP
    carry["bigrams"].add(bigram)
    if cur in carry["last"]:
        guess = prefix.token_strings[carry["last"][cur] + 1]
        if re.fullmatch(r"\d", guess.strip()):
            value += COPIED_DIGIT_BUMP
    carry["last"][cur] = t
    carry["prev"] = cur
    return carry, float(value)

"""Predicts layers.15.mlp.down_proj component 2553 from the kind of the current token.

What the component is: almost entirely one hidden unit of layer 15's MLP (silu(gate) * up,
unit 2553), written back into the residual stream with a gain of about 1.03. Its value is
signed, has a heavy tail, and is nonzero on most tokens. Most of its variance comes from
context that no short rule can read, so this program only captures the coarse trend that
is visible in the token itself:

- colons (":", "::", or any token ending in ":") push it clearly negative;
- sentence-ending "." "!" "?" push it mildly negative;
- digits and ordinary words sit slightly positive;
- a document's first token is always 0 (the component is silent there).

The per-kind values are means measured on training text. They explain about 1% of the
variance, so this is a readable approximation of the trend, not a model of the component.
"""

import re

READS = ()

# Mean activation for each kind of current token, measured on training text.
MEAN = {
    "colon": -0.44,
    "sentence_end": -0.12,
    "punct": 0.05,
    "space": 0.07,
    "digit": 0.17,
    "word": 0.11,
    "other": 0.08,
}


def kind(token):
    """The kind of one token, from its text alone (leading space ignored)."""
    s = token.strip()
    if s in (":", "::", "：") or s.endswith(":"):
        return "colon"
    if s == "":
        return "space"
    if s.isdigit():
        return "digit"
    if re.fullmatch(r"[.!?]+", s):
        return "sentence_end"
    if re.fullmatch(r"\w+", s):
        return "word"
    if re.fullmatch(r"[^\w\s]+", s):
        return "punct"
    return "other"


def step(carry, prefix, upstream):
    t = prefix.position
    if t == 0 or prefix.document_ids[t] != prefix.document_ids[t - 1]:
        return carry, 0.0
    return carry, MEAN[kind(prefix.token_strings[t])]

"""Layer-15 MLP hidden unit 2557, as seen through its down_proj component.

The component's activation is a sum over the layer-15 MLP's hidden units, and its largest
term is this one unit (about 0.95 times the unit's value), which carries roughly 40 to 60
percent of the variance. That unit is strongly negative on the first few tokens of a
document, the more so the closer the token is to the document's start, and is mildly
positive, around 0.1 to 0.4, on later tokens. Beyond the first few tokens the rest of its
value depends on context in ways a short rule does not capture (the other units are
spread out), so this program predicts only the position trend.

The program counts tokens since the current document started (0 = the document's first
token, which is predicted as 0) and returns the typical value at that position:
  - position 1: about -9.7, then each further early position is 0.4 times the one before
    (-3.9, -1.6, -0.6, -0.2 at positions 2 to 5);
  - positions 7 to 16: a slow rise from 0.1 to 0.37;
  - later positions: a constant 0.12.
"""

READS = ()

EARLY_PEAK = -9.7  # value at document position 1
EARLY_DECAY = 0.4  # each earlier-in-document position is this factor of the next
LATE = 0.12  # typical value after position 16


def expected(n):
    """Typical activation at n tokens into the document (n = 0 is its first token)."""
    if n == 0:
        return 0.0
    if n <= 6:
        return EARLY_PEAK * EARLY_DECAY ** (n - 1)
    if n <= 16:
        return 0.1 + 0.03 * (n - 7)
    return LATE


def step(carry, prefix, upstream):
    ids = prefix.document_ids
    new_doc = len(ids) < 2 or ids[-1] != ids[-2]
    n = 0 if new_doc else carry + 1  # tokens since this document started
    return n, expected(n)
